void update_hero_motion_and_collision_probes(void) {
    Vec4 first;
    Vec4 second;
    Vec4 probe;
    f32  base;
    f32  line_probe_hit_distance;
    f32  probe_local_x_offset;
    s32  hit;

    if (hero.tilt_disabled == 0) {
        apply_hero_motion_and_resolve_collisions();
    }
    if (D_L00_0015F5CC % 3 == 0) {
        hero.wall_probe_distance = 4.0f;
        hero.wall_probe_moby_in_class_range = 0;
        hero.wall_probe_hit_moby = 0;
        if (probe_hero_forward_collision(&hero.wall_probe_distance, 0.7f, 4.0f)) {
            hero.wall_normal_pitch =
                fast_arc_tan(coll_hit.normal_z, vector_length_xy(&coll_hit.normal_x));
            if (coll_hit.moby != 0) {
                hero.wall_probe_hit_moby = 1;
                if (is_moby_in_class_range_500_to_540(coll_hit.moby)) {
                    hero.wall_probe_moby_in_class_range = 1;
                }
            }
        }
    }
    if (D_L00_0015F5CC % 5 == 0) {
        hero.edge_ahead = 0;
        hero.edge_drop_depth = 0.0f;
        if (hero.grounded_frames != 0) {
            base = hero.edge_drop_depth;
            transform_hero_local_offset_to_world(&first, 1.1f, base, 1.0f);
            transform_hero_local_offset_to_world(&second, 1.1f, base, -20.0f);
            if (second.f[2] < 0.5f) {
                second.f[2] = 0.5f;
            }
            line_probe_hit_distance = 20.0f;
            hit = collision_line(&first, &second, 2, hero.moby, 0);
            if (hit != 0) {
                line_probe_hit_distance = fast_vec_dist(&first, &coll_hit.point);
                if (!(3.0f < line_probe_hit_distance)) {
                    return;
                }
            }
            /* The loop spells its constants out again. loop.c hoists them and
               cse2 turns 1.1f and 0.0f into copies of the registers that
               already hold them (base is known to be the 0.0f just stored),
               which gives retail's two mov.s before the loop. */
            for (probe_local_x_offset = -0.4f; probe_local_x_offset < 0.5f;
                 probe_local_x_offset += 0.1f) {
                transform_hero_local_offset_to_world(
                    &probe, probe_local_x_offset + 1.1f, 0.0f, 0.0f);
                if (!coll_sphere(hero.capsule_radius, &probe, 2, 0)) {
                    hero.edge_ahead = 1;
                    if (hit == 0) {
                        hero.edge_drop_depth = 20.0f;
                    } else {
                        hero.edge_drop_depth = line_probe_hit_distance;
                    }
                    hero.edge_probe_offset = hero.capsule_radius + probe_local_x_offset;
                    if (hero.edge_probe_offset < 0.0f) {
                        hero.edge_probe_offset = 0.0f;
                    }
                    return;
                }
            }
        }
    }
}

